{"kind":"tool","id":"lKQRXK1ugG0","toolName":"write_file","input":{"path":"src/js/net/minecraft/mod/ModDataKey.js","instructions":"Adds shared validation for mod JSON data keys.","content":"/**
 * Validate a mod data key. Keys are flat names, not paths, so a mod can never
 * escape its own data directory.
 */
export function normalizeModDataKey(key) {
    if (typeof key !== 'string') {
        throw new Error('Mod data key must be a string.');
    }

    const cleaned = key.trim();
    if (!cleaned) {
        throw new Error('Mod data key cannot be empty.');
    }
    if (!/^[A-Za-z0-9._-]{1,64}$/.test(cleaned)) {
        throw new Error(
            `Invalid mod data key '${key}'. Use 1-64 letters, numbers, '.', '_' or '-'.`
        );
    }
    return cleaned;
}

export function modDataPath(modId, key) {
    return `mod_data/${modId}/${normalizeModDataKey(key)}.json`;
}
