async installModFromFolder(files) {
  const entries = Array.from(files || []);
  if (entries.length === 0) throw...
  const normalized = entries.map(file => ({
    file,
    path: String(file.webkitRelativePath || file.name || '').replace(/\\/g,'/').replace(/^\/+/,'')
  })).filter(entry => entry.path && !entry.path.split('/').some(seg => seg==='..'||seg===''));
  const modDataEntries = normalized.filter(e => e.path === 'ModData.js' || e.path.endsWith('/ModData.js'));
  if none throw...
  // choose shallowest ModData.js
  modDataEntries.sort((a,b)=>a.path.split('/').length-b.path.split('/').length)
  const rootPath = modData.path.slice(0, -'ModData.js'.length); // includes trailing slash or ''
  const rootEntries = normalized.filter(e => e.path.startsWith(rootPath));
  if (any other ModData.js outside root?) maybe error "select a single mod folder"
  // parse
  const source = await modData.file.text();
  const modData = this._parseModDataSource(source);
  validate ID and name
  if (this.mods.has(modId)) throw...
  // save metadata
  await saveFile(JSON.stringify(modData), `mods/${id}/ModData.json`)
  // copy files
  for each rootEntry:
    const relative = path.slice(rootPath.length);
    if (!relative) continue;
    if (relative === 'ModData.js') { maybe save as ModData.js }
    const binary = isBinaryModFile(relative) (png/ogg/jpg... etc)
    if binary:
      const b64 = await _arrayBufferToBase64(await file.arrayBuffer());
      await saveBinaryFile(b64, `mods/${id}/${relative}.b64`);
    else:
      const text = await file.text();
      await saveFile(text, `mods/${id}/${relative}`);
  // enable/load
  this.enabledMods.add(id); this._saveEnabledSet();
  await this._loadMod(id)
  return id;
}
