/**
 * Download and install every mod listed in SERVER_MOD_URLS.
 *
 * The list may contain view pages or direct archive links, separated by
 * commas, semicolons or whitespace. Failures are logged and do not prevent
 * the server from starting with the mods that did install.
 */
async function installServerModsFromEnv() {
    const urls = getModUrls();
    if (urls.length === 0) return [];

    const activeServer = config.requestedServer || loadCurrentWorld();
    config.reload(activeServer);

    if (config.serverMods === false) {
        log.warn('ServerMods', `${ENV_KEY} is set, but serverMods is disabled in serverconfig.conf.`);
        return [];
    }

    const modsDir = getServerModsDir();
    fs.mkdirSync(modsDir, { recursive: true });

    const installed = [];
    for (const modUrl of urls) {
        try {
            const result = await installMod(modUrl, modsDir);
            installed.push(result);
            log.info(
                'ServerMods',
                `${result.replaced ? 'Updated' : 'Installed'} '${result.name}' (${result.modId}, ${result.files} files) from ${result.downloadUrl}`
            );
        } catch (error) {
            log.warn('ServerMods', `Could not install mod from '${modUrl}': ${error.message}`);
        }
    }

    clearServerModsCache();
    return installed;
}

module.exports = { installServerModsFromEnv };
